-- The human body. { answer, unit, en_q, en_fact, fr_q, fr_fact, source }
-- Append only: the position in this list is the question's id.
return {
    { 22, "n", "How many bones make up the human skull?", "22: 8 for the cranium and 14 for the face.", "Combien d'os composent le crâne humain ?", "22 : 8 pour la boîte crânienne et 14 pour la face.", "src: Human skull (Gray's Anatomy)" },
    { 26, "n", "How many bones are there in one human foot?", "26 — the two feet hold about a quarter of all your bones.", "Combien d'os compte un pied humain ?", "26 — les deux pieds réunissent environ un quart de nos os.", "src: Foot (anatomy)" },
    { 24, "n", "How many ribs does a human have?", "24, in 12 pairs, men and women alike.", "Combien de côtes a un être humain ?", "24, en 12 paires, chez l'homme comme chez la femme.", "src: Rib cage" },
    { 11000, "l", "About how many litres of air does an adult breathe in a day?", "About 11,000 litres.", "Combien de litres d'air un adulte respire-t-il environ par jour ?", "Environ 11 000 litres.", "src: American Lung Association" },
    { 15, "n", "About how many breaths does an adult take per minute at rest?", "About 12 to 20.", "Combien de respirations un adulte prend-il environ par minute au repos ?", "Environ 12 à 20.", "src: Respiratory rate (normal 12-20)" },
    { 70, "bpm", "About what is a typical adult resting heart rate?", "About 60 to 100 beats a minute; 70 is typical.", "Quelle est environ la fréquence cardiaque d'un adulte au repos ?", "Environ 60 à 100 battements par minute ; 70 est courant.", "src: Heart rate (AHA)" },
    { 1400, "g", "About how much does an adult human brain weigh?", "About 1.4 kg — some 2% of body weight.", "Combien pèse environ un cerveau humain adulte ?", "Environ 1,4 kg — quelque 2 % du poids du corps.", "src: Human brain" },
    { 20, "pct", "About what share of the body's oxygen does the brain use?", "About 20%, for 2% of the body's weight.", "Quelle part environ de l'oxygène du corps le cerveau consomme-t-il ?", "Environ 20 %, pour 2 % du poids du corps.", "src: Brain energy consumption" },
    { 2, "m2", "About how large is the skin of an adult, spread flat?", "About 1.5 to 2 m² — the body's largest organ.", "Quelle est environ la surface de la peau d'un adulte, une fois étalée ?", "Environ 1,5 à 2 m² — le plus grand organe du corps.", "src: Human skin" },
    { 3, "mm", "About how long is the stirrup (stapes), the smallest bone in the body?", "About 3 mm, in the middle ear.", "Quelle est environ la longueur de l'étrier, le plus petit os du corps ?", "Environ 3 mm, dans l'oreille moyenne.", "src: Stapes" },
    { 20, "n", "How many milk teeth does a child have?", "20, replaced by 32 adult teeth.", "Combien de dents de lait a un enfant ?", "20, remplacées par 32 dents définitives.", "src: Deciduous teeth" },
    { 28, "n", "How many teeth does an adult have without the wisdom teeth?", "28; the four wisdom teeth make 32.", "Combien de dents a un adulte sans les dents de sagesse ?", "28 ; les quatre dents de sagesse portent le total à 32.", "src: Human tooth" },
    { 120, "days", "About how long does a red blood cell live?", "About 120 days, then it is recycled by the spleen and liver.", "Combien de temps environ vit un globule rouge ?", "Environ 120 jours.", "src: Red blood cell lifespan" },
    { 2000000, "n", "About how many red blood cells does your body make every second?", "About 2 million, in the bone marrow.", "Combien de globules rouges notre corps fabrique-t-il environ chaque seconde ?", "Environ 2 millions, dans la moelle osseuse.", "src: Erythropoiesis (~2.4 million/s); web-checked" },
    { 1, "cm", "About how much does hair grow in a month?", "About 1 cm, roughly 15 cm a year.", "De combien les cheveux poussent-ils environ en un mois ?", "Environ 1 cm, soit quelque 15 cm par an.", "src: Hair growth (AAD)" },
    { 3, "mm", "About how much does a fingernail grow in a month?", "About 3 mm; toenails grow about three times slower.", "De combien un ongle de la main pousse-t-il environ en un mois ?", "Environ 3 mm ; les ongles des pieds poussent trois fois moins vite.", "src: Nail growth (Yaemsiri 2010: 3.47 mm/month)" },
    { 272, "cm", "How tall was Robert Wadlow, the tallest man ever measured?", "2.72 m, when he died in 1940 at the age of 22.", "Combien mesurait Robert Wadlow, l'homme le plus grand jamais mesuré ?", "2,72 m, à sa mort en 1940, à 22 ans.", "src: Robert Wadlow (Guinness); web-checked" },
    { 4, "n", "How many chambers does the human heart have?", "Four: two atria and two ventricles.", "Combien de cavités compte le cœur humain ?", "Quatre : deux oreillettes et deux ventricules.", "src: Heart" },
    { 5, "n", "How many lobes do the two human lungs have together?", "Five: three on the right, two on the left to make room for the heart.", "Combien de lobes comptent les deux poumons humains réunis ?", "Cinq : trois à droite, deux à gauche pour laisser de la place au cœur.", "src: Lung lobes" },
    { 1500, "g", "About how much does an adult liver weigh?", "About 1.5 kg — the heaviest internal organ.", "Combien pèse environ le foie d'un adulte ?", "Environ 1,5 kg — l'organe interne le plus lourd.", "src: Liver" },
    { 300, "g", "About how much does an adult human heart weigh?", "About 250 to 350 g — the size of a fist.", "Combien pèse environ le cœur d'un adulte ?", "Environ 250 à 350 g — la taille d'un poing.", "src: Heart (mass)" },
    { 4600000, "n", "About how many colour-sensing cones are there in a human eye?", "About 4.6 million in retina counts (6 million is the textbook round figure), against some 90 million rods.", "Combien de cônes, qui perçoivent les couleurs, compte environ un œil humain ?", "Environ 4,6 millions selon les comptages (6 millions dans les manuels), contre quelque 90 millions de bâtonnets.", "src: Curcio et al. 1990 retina counts; web-checked" },
    { 7, "n", "How many vertebrae are there in the human neck?", "Seven — as many as in a giraffe's.", "Combien de vertèbres compte le cou humain ?", "Sept — autant que chez la girafe.", "src: Cervical vertebrae" },
    { 4, "n", "How many blood groups does the ABO system have?", "Four: A, B, AB and O.", "Combien de groupes sanguins compte le système ABO ?", "Quatre : A, B, AB et O.", "src: ABO blood group system" },
    { 180, "l", "About how many litres of blood plasma do the kidneys filter each day?", "About 180 litres; only 1 to 2 litres end up as urine.", "Combien de litres de plasma les reins filtrent-ils environ chaque jour ?", "Environ 180 litres ; seuls 1 à 2 litres finissent en urine.", "src: Glomerular filtration rate" },
    { 120, "ms", "How fast can the quickest nerve signals travel?", "Up to about 120 m/s, over 400 km/h.", "À quelle vitesse les signaux nerveux les plus rapides peuvent-ils circuler ?", "Jusqu'à environ 120 m/s, plus de 400 km/h.", "src: Nerve conduction velocity" },
    { 3, "n", "How many bones are there in the human arm, from shoulder to wrist?", "Three: humerus, radius and ulna.", "Combien d'os compte le bras humain, de l'épaule au poignet ?", "Trois : l'humérus, le radius et le cubitus.", "src: Arm (anatomy)" },
    { 2, "m", "About how long is the DNA in a single human cell, stretched out?", "About 2 metres, packed into a nucleus a few thousandths of a millimetre wide.", "Quelle longueur environ ferait l'ADN d'une seule cellule humaine, déroulé ?", "Environ 2 mètres, dans un noyau de quelques millièmes de millimètre.", "src: Human genome (~2 m per cell)" },
    { 20000, "n", "About how many protein-coding genes does the human genome have?", "About 20,000 — fewer than a grape vine.", "Combien de gènes codant des protéines compte environ le génome humain ?", "Environ 20 000 — moins qu'un pied de vigne.", "src: Human genome (~19,000-20,000); web-checked" },
    { 8, "n", "How many muscles make up the human tongue?", "Eight: four inside it, four anchoring it.", "Combien de muscles composent la langue humaine ?", "Huit : quatre à l'intérieur, quatre qui l'arriment.", "src: Tongue muscles; web-checked" },
    { 7000, "l", "About how many litres of blood does the heart pump in a day?", "About 7,000 litres.", "Combien de litres de sang le cœur pompe-t-il environ par jour ?", "Environ 7 000 litres.", "src: Cardiac output (~5 L/min)" },
    { 20000, "hz", "What is the highest pitch a young human ear can hear?", "About 20,000 Hz; dogs hear up to about 45,000.", "Quelle est la fréquence la plus aiguë qu'entend l'oreille d'un jeune humain ?", "Environ 20 000 Hz ; le chien entend jusqu'à environ 45 000.", "src: Hearing range" },
    { 38, "degc", "From what body temperature, in °C, do doctors usually speak of a fever?", "From 38 °C.", "À partir de quelle température corporelle parle-t-on généralement de fièvre ?", "À partir de 38 °C.", "src: Fever (WHO/clinical threshold)" },
    { 8, "n", "How many bones make up the human wrist?", "Eight small carpal bones, in two rows of four.", "Combien d'os composent le poignet humain ?", "Huit petits os du carpe, en deux rangées de quatre.", "src: Carpal bones (Gray's Anatomy); replaces contested taste-bud count" },
    { 15, "n", "About how many times a minute does a person blink?", "About 15 to 20 times.", "Combien de fois par minute cligne-t-on des yeux environ ?", "Environ 15 à 20 fois.", "src: Blinking rate" },
    { 46, "n", "How many chromosomes come from both parents together in a child's cells?", "46: 23 from the mother, 23 from the father.", "Combien de chromosomes un enfant reçoit-il au total de ses deux parents ?", "46 : 23 de la mère, 23 du père.", "src: Karyotype" },
    { 1, "l", "About how many litres of saliva does a person make in a day?", "About 1 to 1.5 litres.", "Combien de litres de salive produit-on environ par jour ?", "Environ 1 à 1,5 litre.", "src: Saliva" },
}
